import argparse
import copy
import json
import sys
from datetime import date
from urllib.parse import urlparse

DEFAULT_AS_OF = date(2026, 9, 19)
REQUIRED_FAMILIES = {'anthropic','openai','microsoft','google','xai','moonshot-kimi','deepseek','open-weight'}
ALLOWED_KINDS = {'documented','tested','inference','unknown'}
ALLOWED_STATUS = {'documented','qualified','inference'}
MODEL_SURFACES = {'foundation-model'}
HARNESS_SURFACES = {'developer-tool','managed-service','framework','composed-system'}
ROOT_FIELDS = {'schemaVersion','asOf','reviewBy','owner','scope','evidencePolicy','taxonomy','sourceIndex','cases','pairs'}
SOURCE_FIELDS = {'id','title','url','publisher','verifiedAt','reviewBy','owner','trustTier'}
CASE_FIELDS = {'id','providerFamily','experience','surface','observedAt','reviewBy','owner','conclusionClass','conclusionStatus','conclusion','observableBehavior','claims','boundaryNotes','unknowns'}
CLAIM_FIELDS = {'id','kind','claim','sourceIds'}
PAIR_FIELDS = {'providerFamily','modelId','harnessId','relation'}


def parse_date(value, label, errors):
    if not isinstance(value, str):
        errors.append(label + ':bad-date')
        return None
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        errors.append(label + ':bad-date')
        return None
    if parsed.isoformat() != value:
        errors.append(label + ':noncanonical-date')
        return None
    return parsed


def nonempty(value):
    return isinstance(value, str) and bool(value.strip())


def audit(root, as_of):
    errors = []
    stale = []
    if not isinstance(root, dict):
        return ['root:not-object'], stale, None
    missing = ROOT_FIELDS - set(root)
    if missing:
        errors.append('root:missing:' + ','.join(sorted(missing)))
    if root.get('schemaVersion') != '1.0':
        errors.append('root:bad-schema-version')
    if not nonempty(root.get('owner')):
        errors.append('root:empty-owner')
    root_as_of = parse_date(root.get('asOf'), 'root:asOf', errors)
    root_review = parse_date(root.get('reviewBy'), 'root:reviewBy', errors)
    if root_as_of and root_review and root_as_of > root_review:
        errors.append('root:date-order')
    if root_as_of and root_as_of > as_of:
        errors.append('root:future-as-of')
    if root_review and root_review < as_of:
        stale.append('root reviewBy=' + root['reviewBy'])

    sources = root.get('sourceIndex')
    source_by_id = {}
    if not isinstance(sources, list):
        errors.append('sourceIndex:not-list')
        sources = []
    for index, source in enumerate(sources):
        label = 'source[' + str(index) + ']'
        if not isinstance(source, dict):
            errors.append(label + ':not-object')
            continue
        sid = source.get('id')
        if not nonempty(sid):
            errors.append(label + ':bad-id')
            sid = label
        elif sid in source_by_id:
            errors.append(sid + ':duplicate-source-id')
        else:
            source_by_id[sid] = source
        missing_source = SOURCE_FIELDS - set(source)
        if missing_source:
            errors.append(sid + ':missing-source-fields:' + ','.join(sorted(missing_source)))
        if not nonempty(source.get('owner')):
            errors.append(sid + ':empty-source-owner')
        if source.get('trustTier') != 'primary':
            errors.append(sid + ':bad-trust-tier')
        url = source.get('url')
        try:
            parsed_url = urlparse(url) if isinstance(url, str) else None
            valid_url = parsed_url is not None and parsed_url.scheme == 'https' and bool(parsed_url.netloc)
        except ValueError:
            valid_url = False
        if not valid_url:
            errors.append(sid + ':url-not-https')
        verified = parse_date(source.get('verifiedAt'), sid + ':verifiedAt', errors)
        review = parse_date(source.get('reviewBy'), sid + ':reviewBy', errors)
        if verified and review and verified > review:
            errors.append(sid + ':date-order')
        if verified and verified > as_of:
            errors.append(sid + ':future-verification')
        if review and review < as_of:
            stale.append('source ' + sid + ' reviewBy=' + source['reviewBy'])

    cases = root.get('cases')
    case_by_id = {}
    families = set()
    if not isinstance(cases, list):
        errors.append('cases:not-list')
        cases = []
    for index, row in enumerate(cases):
        label = 'case[' + str(index) + ']'
        if not isinstance(row, dict):
            errors.append(label + ':not-object')
            continue
        rid = row.get('id')
        if not nonempty(rid):
            errors.append(label + ':bad-id')
            rid = label
        elif rid in case_by_id:
            errors.append(rid + ':duplicate-case-id')
        else:
            case_by_id[rid] = row
        missing_case = CASE_FIELDS - set(row)
        if missing_case:
            errors.append(rid + ':missing-case-fields:' + ','.join(sorted(missing_case)))
        family = row.get('providerFamily')
        if not nonempty(family):
            errors.append(rid + ':bad-family')
        else:
            families.add(family)
        surface = row.get('surface')
        if not isinstance(surface, str) or not nonempty(surface):
            errors.append(rid + ':bad-surface')
        if not nonempty(row.get('owner')):
            errors.append(rid + ':empty-owner')
        status = row.get('conclusionStatus')
        if not isinstance(status, str) or status not in ALLOWED_STATUS:
            errors.append(rid + ':bad-conclusion-status')
        observed = parse_date(row.get('observedAt'), rid + ':observedAt', errors)
        review = parse_date(row.get('reviewBy'), rid + ':reviewBy', errors)
        if observed and review and observed > review:
            errors.append(rid + ':date-order')
        if observed and observed > as_of:
            errors.append(rid + ':future-observation')
        if review and review < as_of:
            stale.append('case ' + rid + ' reviewBy=' + row['reviewBy'])
        claims = row.get('claims')
        if not isinstance(claims, list) or not claims:
            errors.append(rid + ':claims-not-nonempty-list')
            continue
        for claim_index, claim in enumerate(claims):
            claim_label = rid + ':claim[' + str(claim_index) + ']'
            if not isinstance(claim, dict):
                errors.append(claim_label + ':not-object')
                continue
            missing_claim = CLAIM_FIELDS - set(claim)
            if missing_claim:
                errors.append(claim_label + ':missing-fields:' + ','.join(sorted(missing_claim)))
            kind = claim.get('kind')
            if not isinstance(kind, str) or kind not in ALLOWED_KINDS:
                errors.append(claim_label + ':bad-evidence-kind')
            if not nonempty(claim.get('claim')):
                errors.append(claim_label + ':empty-claim')
            source_ids = claim.get('sourceIds')
            if not isinstance(source_ids, list):
                errors.append(claim_label + ':sourceIds-not-list')
                continue
            bad_element = False
            for source_index, source_id in enumerate(source_ids):
                if not nonempty(source_id):
                    errors.append(claim_label + ':sourceIds[' + str(source_index) + ']:bad-element')
                    bad_element = True
            if bad_element:
                continue
            if kind != 'unknown' and not source_ids:
                errors.append(claim_label + ':missing-source')
            for source_id in source_ids:
                source = source_by_id.get(source_id)
                if source is None:
                    errors.append(claim_label + ':unbound-source:' + source_id)
                elif source.get('owner') != row.get('owner'):
                    errors.append(claim_label + ':cross-family-source:' + source_id)
            if kind == 'tested' and not nonempty(claim.get('runEvidence')):
                errors.append(claim_label + ':tested-without-run-evidence')

    if families != REQUIRED_FAMILIES:
        missing_families = sorted(REQUIRED_FAMILIES - families)
        extra_families = sorted(families - REQUIRED_FAMILIES)
        errors.append('families:not-exact:missing=' + ','.join(missing_families) + ':extra=' + ','.join(extra_families))

    pairs = root.get('pairs')
    valid_pairs = 0
    pair_identities = set()
    if not isinstance(pairs, list):
        errors.append('pairs:not-list')
        pairs = []
    for index, pair in enumerate(pairs):
        label = 'pair[' + str(index) + ']'
        if not isinstance(pair, dict):
            errors.append(label + ':not-object')
            continue
        missing_pair = PAIR_FIELDS - set(pair)
        if missing_pair:
            errors.append(label + ':missing-fields:' + ','.join(sorted(missing_pair)))
            continue
        family = pair.get('providerFamily')
        model_id = pair.get('modelId')
        harness_id = pair.get('harnessId')
        relation = pair.get('relation')
        if not all(nonempty(value) for value in (family, model_id, harness_id, relation)):
            errors.append(label + ':bad-value-shape')
            continue
        if family not in REQUIRED_FAMILIES:
            errors.append(label + ':bad-family')
        if model_id == harness_id:
            errors.append(label + ':roles-not-distinct')
            continue
        identity = (family, model_id, harness_id)
        if identity in pair_identities:
            errors.append(label + ':duplicate-identity')
            continue
        model = case_by_id.get(model_id)
        harness = case_by_id.get(harness_id)
        if model is None or harness is None:
            errors.append(label + ':missing-member')
            continue
        if model.get('providerFamily') != family or harness.get('providerFamily') != family:
            errors.append(label + ':cross-family-member')
            continue
        model_surface = model.get('surface')
        harness_surface = harness.get('surface')
        if not isinstance(model_surface, str) or model_surface not in MODEL_SURFACES or model.get('conclusionClass') != 'model':
            errors.append(label + ':bad-model-role')
            continue
        if not isinstance(harness_surface, str) or harness_surface not in HARNESS_SURFACES or harness.get('conclusionClass') != 'agentic-system':
            errors.append(label + ':bad-harness-role')
            continue
        pair_identities.add(identity)
        valid_pairs += 1
    if valid_pairs < 4:
        errors.append('pairs:need-4-valid')

    counts = (len(cases), len(sources), len(families), valid_pairs)
    return errors, stale, counts


def load_casepack(path):
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            return json.load(handle)
    except OSError as error:
        raise SystemExit('ERROR cannot-read-casepack: ' + str(error))
    except json.JSONDecodeError as error:
        raise SystemExit('ERROR malformed-json: line=' + str(error.lineno) + ' column=' + str(error.colno))


def expect_failure(label, original, mutate, reason, as_of):
    changed = copy.deepcopy(original)
    mutate(changed)
    errors, unused_stale, unused_counts = audit(changed, as_of)
    if reason not in errors:
        raise AssertionError(label + ' expected ' + reason + ' but got ' + ';'.join(errors))
    print('NEGATIVE ' + label + ' PASS ' + reason)


def expect_failure_silent(label, original, mutate, reason, as_of):
    changed = copy.deepcopy(original)
    mutate(changed)
    errors, unused_stale, unused_counts = audit(changed, as_of)
    if reason not in errors:
        raise AssertionError(label + ' expected ' + reason + ' but got ' + ';'.join(errors))


def run_negative_tests(root, as_of):
    expect_failure('missing-source', root, lambda x: x['cases'][0]['claims'][0].__setitem__('sourceIds', []), 'anthropic-claude-api-model:claim[0]:missing-source', as_of)
    expect_failure('cross-family-source', root, lambda x: x['cases'][0]['claims'][0].__setitem__('sourceIds', ['openai-models']), 'anthropic-claude-api-model:claim[0]:cross-family-source:openai-models', as_of)
    expect_failure('tested-without-run-evidence', root, lambda x: x['cases'][0]['claims'][0].__setitem__('kind', 'tested'), 'anthropic-claude-api-model:claim[0]:tested-without-run-evidence', as_of)
    expect_failure('none-row', root, lambda x: x['cases'].__setitem__(0, None), 'case[0]:not-object', as_of)
    expect_failure('malformed-source-index', root, lambda x: x.__setitem__('sourceIndex', None), 'sourceIndex:not-list', as_of)
    expect_failure('bad-date-order', root, lambda x: x['cases'][0].__setitem__('observedAt', '2026-10-26'), 'anthropic-claude-api-model:date-order', as_of)
    expect_failure('empty-owner', root, lambda x: x['cases'][0].__setitem__('owner', ''), 'anthropic-claude-api-model:empty-owner', as_of)
    expect_failure('duplicate-id', root, lambda x: x['cases'][1].__setitem__('id', x['cases'][0]['id']), 'anthropic-claude-api-model:duplicate-case-id', as_of)
    expect_failure('wrong-family-set', root, lambda x: x['cases'][8].__setitem__('providerFamily', 'other'), 'families:not-exact:missing=xai:extra=other', as_of)
    expect_failure('pair-cross-family', root, lambda x: x['pairs'][0].__setitem__('providerFamily', 'openai'), 'pair[0]:cross-family-member', as_of)


def run_silent_assertions(root, as_of):
    original = copy.deepcopy(root)
    expect_failure_silent('surface-shape', root, lambda x: x['cases'][0].__setitem__('surface', []), 'anthropic-claude-api-model:bad-surface', as_of)
    root_errors, unused_stale, unused_counts = audit(None, as_of)
    if 'root:not-object' not in root_errors:
        raise AssertionError('root-shape expected root:not-object but got ' + ';'.join(root_errors))
    future_date = date.fromordinal(as_of.toordinal() + 1).isoformat()
    expect_failure_silent('future-root-as-of', root, lambda x: x.__setitem__('asOf', future_date), 'root:future-as-of', as_of)
    expect_failure_silent('future-source-verification', root, lambda x: x['sourceIndex'][0].__setitem__('verifiedAt', future_date), 'anthropic-messages-api:future-verification', as_of)
    expect_failure_silent('duplicate-pair-identity', root, lambda x: x.__setitem__('pairs', [copy.deepcopy(x['pairs'][0]) for unused in range(4)]), 'pair[1]:duplicate-identity', as_of)
    expect_failure_silent('bad-case-id', root, lambda x: x['cases'][0].__setitem__('id', []), 'case[0]:bad-id', as_of)
    expect_failure_silent('bad-family', root, lambda x: x['cases'][0].__setitem__('providerFamily', []), 'anthropic-claude-api-model:bad-family', as_of)
    expect_failure_silent('bad-status', root, lambda x: x['cases'][0].__setitem__('conclusionStatus', []), 'anthropic-claude-api-model:bad-conclusion-status', as_of)
    expect_failure_silent('bad-source-element', root, lambda x: x['cases'][0]['claims'][0].__setitem__('sourceIds', [[]]), 'anthropic-claude-api-model:claim[0]:sourceIds[0]:bad-element', as_of)
    expect_failure_silent('bad-pair-shape', root, lambda x: x['pairs'].__setitem__(0, []), 'pair[0]:not-object', as_of)
    if root != original:
        raise AssertionError('input-immutability failed')
    changed = copy.deepcopy(root)
    changed['cases'][0]['surface'] = []
    if root['cases'][0]['surface'] == []:
        raise AssertionError('deepcopy isolation failed')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('casepack', nargs='?', default='casepack.json')
    parser.add_argument('--as-of', default=DEFAULT_AS_OF.isoformat())
    args = parser.parse_args()
    try:
        as_of = date.fromisoformat(args.as_of)
    except ValueError:
        raise SystemExit('ERROR --as-of must be YYYY-MM-DD')
    if as_of.isoformat() != args.as_of:
        raise SystemExit('ERROR --as-of must be YYYY-MM-DD')
    root = load_casepack(args.casepack)
    errors, stale, counts = audit(root, as_of)
    if isinstance(root, dict):
        print('SNAPSHOT asOf=' + str(root.get('asOf')) + ' reviewBy=' + str(root.get('reviewBy')) + ' auditAsOf=' + as_of.isoformat())
    else:
        print('ERROR root:not-object')
    if errors:
        for error in errors:
            if not (error == 'root:not-object' and not isinstance(root, dict)):
                print('ERROR ' + error)
        print('BLOCKED structural-errors=' + str(len(errors)))
        return 1
    if stale:
        for item in stale:
            print('STALE ' + item)
        print('BLOCKED stale-items=' + str(len(stale)))
        return 1
    run_negative_tests(root, as_of)
    run_silent_assertions(root, as_of)
    case_count, source_count, family_count, pair_count = counts
    print('PASS cases=' + str(case_count) + ' sources=' + str(source_count) + ' families=' + str(family_count) + ' valid-pairs=' + str(pair_count))
    return 0


if __name__ == '__main__':
    sys.exit(main())
